SELECT DISTINCT gt.subject_id AS userId, r.role_code AS code FROM grant_table gt JOIN sys_role r ON r.id = gt.role_id WHERE gt.subject_type = 'USER' AND gt.subject_id IN
#{userId}
AND r.status = 1

WITH all_role_ids AS ( SELECT DISTINCT gt.subject_id AS user_id, r.id AS role_id FROM grant_table gt JOIN sys_role r ON r.id = gt.role_id WHERE gt.subject_type = 'USER' AND gt.subject_id IN
#{userId}
AND r.status = 1 ) SELECT DISTINCT ar.user_id AS userId, p.permission_code AS code FROM sys_role_permission rp JOIN all_role_ids ar ON rp.role_id = ar.role_id JOIN sys_permission p ON p.id = rp.permission_id WHERE p.status = 1
